PROGRAM ST460_PRESSBETJANING
VAR
    steg         : INT := 0;
    trigReset    : R_TRIG;
    tmrPress     : TON;
    xLarm        : BOOL := FALSE;
    xKravOmstart : BOOL := TRUE;
    xDrift       : BOOL := FALSE;
    xStopptidOK  : BOOL := FALSE;
    xRidaOK      : BOOL := FALSE;
END_VAR

trigReset(CLK := SYS_RESET);
tmrPress(IN := ST460_PRS_STROKE, PT := T#1400ms);

(* Ett brutet nodstopp staller ut omstartskvittensen. Att donet dras upp igen
   far aldrig i sig starta cellen. *)
IF NOT EMG_OK THEN
    xKravOmstart := TRUE;
END_IF;

(* Den uppmatta stopptiden ar den storhet hela sakerhetsavstandet ar raknat ur.
   Over 275,0 ms racker inte de 688 mm ridan sitter pa. Under 200,0 ms har
   mataren inte fangat hela stoppet, och ett for kort varde ger ett for kort
   avstand. Bada fallen ar larm. *)
xStopptidOK := ST460_STP_TIME >= 200.0 AND ST460_STP_TIME <= 275.0;
IF ST460_STP_TIME > 275.0 THEN
    xLarm := TRUE;
END_IF;
IF ST460_STP_TIME > 0.0 AND ST460_STP_TIME < 200.0 THEN
    xLarm := TRUE;
END_IF;

(* Mutingen kraver BADA givarna och lases pa niva varje scan. En ensam givare
   mutar ingenting, och mutingen upphor i samma scan som en givare faller. *)
ST460_MUT_ON := EMG_OK AND AIR_OK AND SYS_AUTO AND ST460_MUT_A AND ST460_MUT_B
                AND NOT xLarm AND NOT xKravOmstart;

(* Ridan ar overbryggad bara av en giltig muting. Bryts den utan muting ar det
   ett skyddsstopp som kraver kvittens. *)
xRidaOK := ST460_LGT_CLEAR OR ST460_MUT_ON;
IF NOT xRidaOK THEN
    xKravOmstart := TRUE;
END_IF;

IF trigReset.Q AND EMG_OK AND AIR_OK AND xRidaOK THEN
    xLarm := FALSE;
    xKravOmstart := FALSE;
END_IF;

SYS_ALARM := xLarm;

xDrift := EMG_OK AND AIR_OK AND SYS_AUTO AND xRidaOK
          AND NOT xLarm AND NOT xKravOmstart;

IF xDrift THEN
    CASE steg OF
        0:
            ST460_PRS_STROKE := FALSE;
            IF ST460_PRT_PRS THEN
                ST460_CNV_RUN := FALSE;
                ST460_RB_START := TRUE;
                steg := 1;
            ELSE
                ST460_CNV_RUN := TRUE;
            END_IF;
        1:
            IF ST460_RB_DONE THEN
                ST460_RB_START := FALSE;
                steg := 2;
            END_IF;
        2:
            (* Slaget kraver fri rida, ingen arm kvar i zonen, koppen i ovre
               lage och en uppmatt stopptid som avstandet haller for. *)
            IF ST460_LGT_CLEAR AND NOT ST460_MUT_ON AND ST460_PRS_TDC
               AND xStopptidOK THEN
                ST460_PRS_STROKE := TRUE;
                steg := 3;
            END_IF;
        3:
            IF tmrPress.Q THEN
                ST460_PRS_STROKE := FALSE;
                steg := 0;
            END_IF;
    ELSE
        steg := 0;
    END_CASE;
ELSE
    ST460_PRS_STROKE := FALSE;
    ST460_RB_START := FALSE;
    ST460_CNV_RUN := FALSE;
    steg := 0;
END_IF;
END_PROGRAM

